package id.sapu.berita;

import android.content.Context;
import android.net.Uri;

import org.json.JSONArray;
import org.json.JSONObject;

import java.io.ByteArrayOutputStream;
import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.LinkedHashSet;
import java.util.List;
import java.util.Locale;
import java.util.Set;
import java.util.regex.Pattern;

/**
 * The supported news sites and what counts as an article on each. Generated by `npm run build` into
 * assets/domains.json from the same rules the cleaner uses (rules/sites).
 */
final class NewsSites {
    private static NewsSites instance;

    private static final class Site {
        final List<String> domains = new ArrayList<>();
        Pattern article;
    }

    private final List<Site> sites = new ArrayList<>();

    static synchronized NewsSites get(Context context) {
        if (instance == null) instance = new NewsSites(context.getApplicationContext());
        return instance;
    }

    private NewsSites(Context context) {
        try (InputStream in = context.getAssets().open("domains.json")) {
            JSONArray list = new JSONObject(readAll(in)).getJSONArray("sites");
            for (int i = 0; i < list.length(); i++) {
                JSONObject s = list.getJSONObject(i);
                Site site = new Site();
                JSONArray d = s.getJSONArray("domains");
                for (int j = 0; j < d.length(); j++) site.domains.add(d.getString(j).toLowerCase(Locale.ROOT));
                try {
                    site.article = Pattern.compile(s.getString("article"));
                } catch (RuntimeException e) {
                    site.article = null; // unparsable in Java: treat every page on the site as non-article
                }
                sites.add(site);
            }
        } catch (Exception e) {
            // No asset (a build without `npm run build`): nothing is treated as news.
        }
    }

    /** All registrable domains, e.g. for the setup screen's "active on N of M sites". */
    Set<String> domains() {
        Set<String> all = new LinkedHashSet<>();
        for (Site s : sites) all.addAll(s.domains);
        return all;
    }

    /** A news article we can clean (supported host and an article-shaped path). */
    boolean isArticle(Uri uri) {
        Site site = siteFor(uri);
        String path = uri == null ? null : uri.getPath();
        return site != null && site.article != null && path != null && site.article.matcher(path).find();
    }

    private Site siteFor(Uri uri) {
        if (uri == null) return null;
        String scheme = uri.getScheme();
        if (!"https".equals(scheme) && !"http".equals(scheme)) return null;
        String host = uri.getHost();
        if (host == null) return null;
        host = host.toLowerCase(Locale.ROOT);
        for (Site s : sites) {
            for (String d : s.domains) {
                if (host.equals(d) || host.endsWith("." + d)) return s;
            }
        }
        return null;
    }

    private static String readAll(InputStream in) throws java.io.IOException {
        ByteArrayOutputStream out = new ByteArrayOutputStream();
        byte[] buf = new byte[8192];
        for (int n; (n = in.read(buf)) > 0; ) out.write(buf, 0, n);
        return out.toString(StandardCharsets.UTF_8.name());
    }
}
